// Kontener zarzadza serwletem przez 3 kluczowe metody:
// 1) init(ServletConfig) - wywolywane RAZ, przy pierwszym uzyciu
// 2) service(request, response) - wywolywane PRZY KAZDYM zadaniu HTTP
//    HttpServlet ma juz gotowa implementacje service(), ktora sama
//    sprawdza metode HTTP i przekazuje do doGet()/doPost()/doPut()...
// 3) destroy() - wywolywane RAZ, tuz przed usunieciem serwletu

class HelloServlet extends HttpServlet {
    @Override
    public void init(ServletConfig config) throws ServletException {
        super.init(config);
        System.out.println("init() - wywolane RAZ");
    }
    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        resp.setContentType("text/plain");
        resp.getWriter().println("Hello from servlet!");
    }
    @Override
    public void destroy() {
        System.out.println("destroy() - wywolane RAZ");
        super.destroy();
    }
}
// Kolejnosc: init() -> service() (wielokrotnie) -> destroy()

// Kanoniczny wzorzec calego rozdzialu - uruchamiamy Tomcata
// PROGRAMOWO w main(), bez zadnej zewnetrznej instalacji serwera.

Tomcat tomcat = new Tomcat();
tomcat.setBaseDir(Files.createTempDirectory("lesson01").toString());
tomcat.getConnector().setPort(0); // port 0 = system wybiera wolny port

Context context = tomcat.addContext("", null);
Tomcat.addServlet(context, "helloServlet", new HelloServlet());
context.addServletMappingDecoded("/hello", "helloServlet");

try {
    tomcat.start();
    int port = tomcat.getConnector().getLocalPort();
    // wyslij zadanie HttpClientem na http://localhost:<port>/hello
} finally {
    tomcat.stop();
    tomcat.destroy(); // destroy() serwletu wywola sie teraz
}
